CREATE OR REPLACE FUNCTION public.challenge_final_schedule_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.model='goal' AND NEW.goal_target>(CASE WHEN NEW.frequency='weekly' THEN ceil((NEW.ends_on-NEW.starts_on+1)/7.0)::int ELSE NEW.ends_on-NEW.starts_on+1 END) THEN RAISE EXCEPTION 'invalid_rules'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER challenge_final_schedule BEFORE INSERT OR UPDATE ON public.challenges FOR EACH ROW EXECUTE FUNCTION public.challenge_final_schedule_guard();
CREATE OR REPLACE FUNCTION public.guard_challenge_message_schedule() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c challenges; BEGIN SELECT * INTO c FROM challenges WHERE id=NEW.challenge_id; IF NEW.enabled AND (NEW.kind<>'welcome' OR NEW.send_offset_days<>0 OR length(trim(NEW.body_en||NEW.body_es))=0) OR NEW.send_hour NOT BETWEEN 0 AND 23 OR NEW.send_offset_days NOT BETWEEN -7 AND c.ends_on-c.starts_on+1 THEN RAISE EXCEPTION 'invalid_messages'; END IF; RETURN NEW; END; $$;
REVOKE ALL ON FUNCTION public.challenge_final_schedule_guard() FROM PUBLIC,anon,authenticated;